#!/usr/bin/env bash
# Issue 366: re-fold every tender whose head value is a repdigit field-width
# maximum, so the standing rows catch up with sentinel_amount. Two legs: the
# major-unit repdigit the rule has always refused (249 tenders, never in any
# earlier cohort — those drained negatives and >EUR 100bn only), and the
# nines-in-cents leg added by 7c8a443 (73 tenders).
#
# The cohort is an explicit VALUE LIST, not a predicate: every value both legs
# refuse is a finite set under i64, so each is an index seek on
# tenders_current_value_eur. Bounded and exact, where a predicate over the tail
# would be a scan. Blind to non-EUR published sentinels by construction — this
# reads the CONVERTED column, and a PLN nines-run converts to something else.
set -uo pipefail
set -a; . /root/tender-admin-secret; set +a
A=(-s -m 300 -H "x-admin-secret: $TENDER_ADMIN_SECRET")
J=http://127.0.0.1:8080/admin/jobs
VALUES="111111111,222222222,333333333,444444444,555555555,666666666,777777777,888888888,999999999,1111111111,2222222222,3333333333,4444444444,5555555555,6666666666,7777777777,8888888888,9999999999,11111111100,11111111111,22222222200,22222222222,33333333300,33333333333,44444444400,44444444444,55555555500,55555555555,66666666600,66666666666,77777777700,77777777777,88888888800,88888888888,99999999900,99999999999,111111111100,111111111111,222222222200,222222222222,333333333300,333333333333,444444444400,444444444444,555555555500,555555555555,666666666600,666666666666,777777777700,777777777777,888888888800,888888888888,999999999900,999999999999,1111111111100,1111111111111,2222222222200,2222222222222,3333333333300,3333333333333,4444444444400,4444444444444,5555555555500,5555555555555,6666666666600,6666666666666,7777777777700,7777777777777,8888888888800,8888888888888,9999999999900,9999999999999,11111111111100,11111111111111,22222222222200,22222222222222,33333333333300,33333333333333,44444444444400,44444444444444,55555555555500,55555555555555,66666666666600,66666666666666,77777777777700,77777777777777,88888888888800,88888888888888,99999999999900,99999999999999,111111111111100,111111111111111,222222222222200,222222222222222,333333333333300,333333333333333,444444444444400,444444444444444,555555555555500,555555555555555,666666666666600,666666666666666,777777777777700,777777777777777,888888888888800,888888888888888,999999999999900,999999999999999,1111111111111100,1111111111111111,2222222222222200,2222222222222222,3333333333333300,3333333333333333,4444444444444400,4444444444444444,5555555555555500,5555555555555555,6666666666666600,6666666666666666,7777777777777700,7777777777777777,8888888888888800,8888888888888888,9999999999999900,9999999999999999,11111111111111100,11111111111111111,22222222222222200,22222222222222222,33333333333333300,33333333333333333,44444444444444400,44444444444444444,55555555555555500,55555555555555555,66666666666666600,66666666666666666,77777777777777700,77777777777777777,88888888888888800,88888888888888888,99999999999999900,99999999999999999,111111111111111100,111111111111111111,222222222222222200,222222222222222222,333333333333333300,333333333333333333,444444444444444400,444444444444444444,555555555555555500,555555555555555555,666666666666666600,666666666666666666,777777777777777700,777777777777777777,888888888888888800,888888888888888888,999999999999999900,999999999999999999,1111111111111111100,2222222222222222200,3333333333333333300,4444444444444444400,5555555555555555500,6666666666666666600,7777777777777777700,8888888888888888800"

idle() { for _ in $(seq 1 240); do
  c=$(curl "${A[@]}" "$J?limit=1" | python3 -c 'import json,sys; print(json.load(sys.stdin).get("current") or "")' 2>/dev/null)
  [ -z "$c" ] && return 0; sleep 5; done; return 1; }

for round in $(seq 1 6); do
  left=$(echo "SELECT COUNT(*) FROM tenders t WHERE t.current_value_eur_cents IN ($VALUES) AND EXISTS (SELECT 1 FROM tender_version_amounts a WHERE a.tender_id = t.id AND a.seq = t.current_seq AND a.eur_cents = t.current_value_eur_cents AND a.cents IN ($VALUES))" \
         | bash /root/sq.sh | python3 -c 'import json,sys; print(json.load(sys.stdin)["rows"][0][0])')
  echo "round $round: $left repdigit head value(s) left"
  [ "$left" -eq 0 ] && { echo "DRAINED"; break; }
  echo "SELECT DISTINCT v.caused_by_notice_id FROM tenders t JOIN tender_versions v ON v.tender_id = t.id AND v.seq = t.current_seq WHERE t.current_value_eur_cents IN ($VALUES) AND EXISTS (SELECT 1 FROM tender_version_amounts a WHERE a.tender_id = t.id AND a.seq = t.current_seq AND a.eur_cents = t.current_value_eur_cents AND a.cents IN ($VALUES)) ORDER BY 1 LIMIT 1000" \
    | bash /root/sq.sh \
    | python3 -c 'import json,sys; d=json.load(sys.stdin); json.dump({"kind":"refold-notices","notices":[r[0] for r in d["rows"]]}, open("/tmp/br.json","w"))'
  n=$(python3 -c 'import json; print(len(json.load(open("/tmp/br.json"))["notices"]))')
  [ "$n" -eq 0 ] && { echo "no ids returned though $left remain — stopping"; exit 1; }
  echo "  enqueuing refold of $n notice(s)"
  curl "${A[@]}" -X POST -H 'content-type: application/json' --data-binary @/tmp/br.json "$J" >/dev/null
  idle || { echo "queue did not drain in 20 min — stopping"; exit 1; }
done
rm -f /tmp/br.json
echo "SELECT COUNT(*) AS repdigit_left FROM tenders t WHERE t.current_value_eur_cents IN ($VALUES) AND EXISTS (SELECT 1 FROM tender_version_amounts a WHERE a.tender_id = t.id AND a.seq = t.current_seq AND a.eur_cents = t.current_value_eur_cents AND a.cents IN ($VALUES))" | bash /root/sq.sh
